arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -d "token=<TOKEN>" -d "types=public_channel,private_channel" -d "limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR', d.get('error')); sys.exit()
for c in d['channels']:
    if 'launch' in c.get('name','').lower():
        print(c['id'], c['name'], 'archived' if c.get('is_archived') else 'active')
"

